const id = String($json.proposal_id || '').trim();
if (!/^PROP-[A-F0-9]{12}$/.test(id)) throw new Error('VALIDATION_ERROR: invalid proposal_id');
return [{json:{...$json, proposal_id:id}}];

const p=$json;
if(p.status!=='PENDING') throw new Error(`APPROVAL_DENIED: proposal is ${p.status}`);
return [{json:{approval_request:{proposal_id:p.proposal_id,ticket_id:p.ticket_id,proposed_note:p.proposed_note,proposed_status:p.proposed_status,reason:p.reason,ticket_version:p.ticket_version,expires_at:p.expires_at,correlation_id:p.correlation_id},trusted_context:{proposal_id:p.proposal_id,session_id:p.session_id,ticket_version:p.ticket_version,correlation_id:p.correlation_id},instruction:'Review every field. The Wait response records review intent only; it is not authentication and cannot apply the ticket change.'}}];

const decision=String($json.body?.decision || $json.decision || '').toUpperCase();
